public async IAsyncEnumerable<Message> ReceiveAllAsync(
    string queueUrl,
    [EnumeratorCancellation] CancellationToken cancellationToken)
{
    while (!cancellationToken.IsCancellationRequested)
    {
        var response = await _sqs.ReceiveMessageAsync(queueUrl, cancellationToken);
        if (response.Messages.Count == 0) yield break;

        foreach (var message in response.Messages)
            yield return message;
    }
}

public async Task DrainAsync(string queueUrl, CancellationToken cancellationToken)
{
    await foreach (var message in ReceiveAllAsync(queueUrl)
        .WithCancellation(cancellationToken))
    {
        await HandleAsync(message, cancellationToken);
    }
}

public async IAsyncEnumerable<AttemptRow> ReadAttemptsAsync(
    string filePath,
    [EnumeratorCancellation] CancellationToken cancellationToken)
{
    using var reader = new StreamReader(filePath);
    await reader.ReadLineAsync(cancellationToken); // skip header

    while (!reader.EndOfStream)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var line = await reader.ReadLineAsync(cancellationToken);
        if (line is null) break;

        var cols = line.Split(',');
        if (cols.Length >= 3)
            yield return new AttemptRow(cols[0], cols[1], int.Parse(cols[2]));
    }
}

